root = etree.fromstring(files['word/document.xml'])
accept_changes(root)

# Remove prior Draft 2 literal-deletion blocks that were stored as display text rather
# than Word revision elements (party block, old signature blocks, and one old bullet).
for p in list(root.xpath('.//w:p', namespaces=NS)):
    t = ptext(p)
    if ('[DELETED:' in t or '\\[DELETED:' in t) and '[ADDED:' not in t and '\\[ADDED:' not in t:
        parent = p.getparent()
        if parent is None:
            continue
        start = parent.index(p)
        parent.remove(p)
        # For a multi-paragraph deleted block, remove through its literal closing bracket.
        while start < len(parent):
            nxt = parent[start]
            if nxt.tag != qn('p'):
                break
            nt = ptext(nxt)
            parent.remove(nxt)
            if ']' in nt or '\\]' in nt:
                break
# Remove the connector from the deleted party-identification block if it survived.
for p in list(root.xpath('.//w:p', namespaces=NS)):
    if ptext(p).strip() == 'and':
        prev = p.getprevious()
        if prev is not None and '[DELETED:' in ptext(prev):
            p.getparent().remove(p)

# Remove literal bracket labels left in the prior draft's presentation layer after accepting Draft 2.
for t in root.xpath('.//w:t', namespaces=NS):
    s = t.text or ''

